export default function ContactForm() {
  async function submitContact(formData: FormData) {
    'use server';

    const name = formData.get('name');
    const email = formData.get('email');
    const message = formData.get('message');

    // JavaScript validation
    if (!name || typeof name !== 'string' || name.trim() === '') {
      throw new Error('Name is required');
    }
    if (!email || typeof email !== 'string' || email.trim() === '' || !email.includes('@')) {
      throw new Error('Valid email is required');
    }
    if (!message || typeof message !== 'string' || message.trim() === '') {
      throw new Error('Message is required');
    }

    // Simulate saving the contact message
    console.log('Contact form submitted:', { name, email, message });

    // In a real application, you would save this to a database
  }

  return (
    <div style={{ maxWidth: '400px', margin: '20px auto', padding: '20px', border: '1px solid #ccc', borderRadius: '8px' }}>
      <h2>Contact Us</h2>
      <form action={submitContact} style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
        <div>
          <label htmlFor="name" style={{ display: 'block', marginBottom: '5px' }}>Name</label>
          <input 
            type="text" 
            id="name" 
            name="name" 
            placeholder="Your Name" 
            required 
            style={{ width: '100%', padding: '8px', border: '1px solid #ddd', borderRadius: '4px' }}
          />
        </div>

        <div>
          <label htmlFor="email" style={{ display: 'block', marginBottom: '5px' }}>Email</label>
          <input 
            type="email" 
            id="email" 
            name="email" 
            placeholder="your@email.com" 
            required 
            style={{ width: '100%', padding: '8px', border: '1px solid #ddd', borderRadius: '4px' }}
          />
        </div>

        <div>
          <label htmlFor="message" style={{ display: 'block', marginBottom: '5px' }}>Message</label>
          <textarea 
            id="message" 
            name="message" 
            placeholder="Your message here..." 
            rows={4} 
            required 
            style={{ width: '100%', padding: '8px', border: '1px solid #ddd', borderRadius: '4px' }}
          />
        </div>

        <button 
          type="submit" 
          style={{ padding: '10px', backgroundColor: '#0070f3', color: 'white', border: 'none', borderRadius: '4px', cursor: 'pointer' }}
        >
          Send Message
        </button>
      </form>
    </div>
  );
}

